local FlourSieveMaker = {}
local PRODUCTS = {
    iron_floursieve = { name = "Železni sitana za moko", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sitana za moko za mlinarje." },
    bronze_floursieve = { name = "Bronast sitana za moko", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sitana za moko za mlinarje." },
    silver_floursieve = { name = "Srebrn sitana za moko", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sitana za moko za mlinarje." },
    gilded_floursieve = { name = "Pozlačen sitana za moko", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sitana za moko za mlinarje." },
    jewel_set_floursieve = { name = "Draguljast sitana za moko", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sitana za moko za mlinarje." },
    royal_sovereign_floursieve = { name = "Kraljevski suveren sitana za moko", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sitana za moko z biseri za krono." },
}
local BUILDINGS = {
    floursieve_workshop = { name = "Floursieve delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    floursieve_house = { name = "Floursieve hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_floursieve_atelier = { name = "Mojstrski floursieve atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_floursieve_palace = { name = "Suverena floursieve palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
FlourSieveMaker.ironStock=14; FlourSieveMaker.bronzeStock=12; FlourSieveMaker.woodStock=14; FlourSieveMaker.leatherStock=10; FlourSieveMaker.silverStock=8; FlourSieveMaker.goldStock=6; FlourSieveMaker.jewelStock=4; FlourSieveMaker.pearlStock=4
FlourSieveMaker.productStock = {}; FlourSieveMaker.buildings = {}; FlourSieveMaker.maker = nil; FlourSieveMaker.activeMaking = {}; FlourSieveMaker.totalProducts = 0; FlourSieveMaker.dayTimer = 0
function FlourSieveMaker.init() FlourSieveMaker.ironStock=14; FlourSieveMaker.bronzeStock=12; FlourSieveMaker.woodStock=14; FlourSieveMaker.leatherStock=10; FlourSieveMaker.silverStock=8; FlourSieveMaker.goldStock=6; FlourSieveMaker.jewelStock=4; FlourSieveMaker.pearlStock=4; FlourSieveMaker.productStock={}; FlourSieveMaker.buildings={}; FlourSieveMaker.maker=nil; FlourSieveMaker.activeMaking={}; FlourSieveMaker.totalProducts=0; FlourSieveMaker.dayTimer=0; print("[FlourSieveMaker] Royal Flour Sieve Maker System initialized (6 products, 4 buildings)") end
function FlourSieveMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FlourSieveMaker.maker={name=n or ("Sitnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sitnikar najet: %s (spretnost: %d)",FlourSieveMaker.maker.name,s),"success") end; return true end
function FlourSieveMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FlourSieveMaker.build(id) local ok,e=FlourSieveMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FlourSieveMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FlourSieveMaker.getQualityBonus() local b=0; for _,bd in ipairs(FlourSieveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FlourSieveMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and FlourSieveMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and FlourSieveMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and FlourSieveMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and FlourSieveMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and FlourSieveMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FlourSieveMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FlourSieveMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FlourSieveMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FlourSieveMaker.buildings==0 then return false,"Potrebna sitnična delavnica" end; if not FlourSieveMaker.maker then return false,"Potreben sitnikar" end; return true end
function FlourSieveMaker.make(pt,qty) qty=qty or 1; local ok,e=FlourSieveMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then FlourSieveMaker.ironStock=FlourSieveMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then FlourSieveMaker.bronzeStock=FlourSieveMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then FlourSieveMaker.woodStock=FlourSieveMaker.woodStock-d.woodCost*qty end; if d.leatherCost then FlourSieveMaker.leatherStock=FlourSieveMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then FlourSieveMaker.silverStock=FlourSieveMaker.silverStock-d.silverCost*qty end; if d.goldCost then FlourSieveMaker.goldStock=FlourSieveMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FlourSieveMaker.jewelStock=FlourSieveMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FlourSieveMaker.pearlStock=FlourSieveMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FlourSieveMaker.maker then t=math.max(1,t-math.floor(FlourSieveMaker.maker.skill/13)) end; table.insert(FlourSieveMaker.activeMaking,{id="floursieve_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FlourSieveMaker.completeMaking(m) local q=1.0+(FlourSieveMaker.getQualityBonus()/100); if FlourSieveMaker.maker then q=q+(FlourSieveMaker.maker.skill/140) end; q=math.min(2.5,q); FlourSieveMaker.productStock[m.productType]=(FlourSieveMaker.productStock[m.productType] or 0)+m.quantity; FlourSieveMaker.totalProducts=FlourSieveMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FlourSieveMaker.maker then FlourSieveMaker.maker.itemsMade=FlourSieveMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FlourSieveMaker.maker.skill=math.min(100,FlourSieveMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sito izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"floursieve.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function FlourSieveMaker.update(dt) if not _G.state then return end; FlourSieveMaker.dayTimer=FlourSieveMaker.dayTimer+dt; if FlourSieveMaker.dayTimer>=30 then FlourSieveMaker.dayTimer=0; for i=#FlourSieveMaker.activeMaking,1,-1 do local m=FlourSieveMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FlourSieveMaker.completeMaking(m); table.remove(FlourSieveMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FlourSieveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FlourSieveMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FlourSieveMaker.getStats() return {ironStock=FlourSieveMaker.ironStock,bronzeStock=FlourSieveMaker.bronzeStock,woodStock=FlourSieveMaker.woodStock,leatherStock=FlourSieveMaker.leatherStock,silverStock=FlourSieveMaker.silverStock,goldStock=FlourSieveMaker.goldStock,jewelStock=FlourSieveMaker.jewelStock,pearlStock=FlourSieveMaker.pearlStock,productStock=FlourSieveMaker.productStock,numBuildings=#FlourSieveMaker.buildings,hasMaker=FlourSieveMaker.maker~=nil,makerName=FlourSieveMaker.maker and FlourSieveMaker.maker.name or "—",makerSkill=FlourSieveMaker.maker and FlourSieveMaker.maker.skill or 0,activeMaking=#FlourSieveMaker.activeMaking,totalProducts=FlourSieveMaker.totalProducts} end
return FlourSieveMaker
